from typing import List

class Solution:
    def canVisitAllRooms(self, rooms: List[List[int]]) -> bool:
        # DFS follows keys as directed edges.
        seen, stack = {0}, [0]
        while stack:
            room = stack.pop()
            for key in rooms[room]:
                if key not in seen:
                    seen.add(key); stack.append(key)
        return len(seen) == len(rooms)

